	ctx := context.Background()

	b := retry.NewFibonacci(1 * time.Second)
	b = retry.WithFullJitter(b)

	if err := retry.Do(ctx, b, func(_ context.Context) error {
		// TODO: logic here
		return nil
	}); err != nil {
		// handle error
	}
}

